const root='C:/Dev/EasyEDA/EasyEDA-Project/STM32H747 board';
const [page,expectedHash]=__taskArgs;
if(!['03','06'].includes(page)||!/^[a-f0-9]{64}$/.test(expectedHash||''))throw new Error('Explicit reviewed page and candidate SHA256 required');
const uuid=page==='03'?'360993a3108b5759':'a07bf8e4331877a8';
const load=async path=>{const f=await eda.sys_FileSystem.readFileFromFileSystem(path);if(!f)throw new Error('Missing reviewed input '+path);return await f.text();};
const parse=s=>s.split(/\r?\n/).filter(x=>x.includes('||')).map(x=>{const p=x.indexOf('||'),v=x.slice(p+2).replace(/\|$/,'');return{h:JSON.parse(x.slice(0,p)),b:v?JSON.parse(v):''};});
const canonical=v=>JSON.stringify(v,(_,q)=>q&&typeof q==='object'&&!Array.isArray(q)?Object.fromEntries(Object.entries(q).sort(([a],[b])=>a.localeCompare(b))):q);
const hash=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(v=>v.toString(16).padStart(2,'0')).join('');
const plan=JSON.parse(await load(root+'/output/candidates/adc10-labtool-20261018/schematic-plan.json'));
const item=plan.pages.find(x=>x.pageUuid===uuid);
if(!item||item.candidateSha256!==expectedHash)throw new Error('Reviewed page plan/hash mismatch');
const candidate=await load(item.candidatePath),baselineText=await load(item.baselinePath);
if(await hash(candidate)!==expectedHash||await hash(baselineText)!==item.baselineSha256)throw new Error('Candidate or baseline file changed');
await eda.dmt_EditorControl.openDocument(uuid);
if((await eda.dmt_SelectControl.getCurrentDocumentInfo())?.uuid!==uuid)throw new Error('Wrong schematic page');
const before=parse(await eda.sys_FileManager.getDocumentSource()),baseline=parse(baselineText);
const live=new Map(before.map(r=>[r.h.type+':'+r.h.id,r]));
if(before[0]?.b.uuid!==uuid||before.length!==baseline.length)throw new Error('Baseline page identity/count changed');
for(const r of baseline)if(!['DOCHEAD','CANVAS'].includes(r.h.type)&&canonical(live.get(r.h.type+':'+r.h.id)?.b)!==canonical(r.b))throw new Error('Preexisting page changed '+r.h.type+':'+r.h.id);
const parsed=parse(candidate);
if(parsed[0]?.b.uuid!==uuid||parsed[0]?.b.docType!=='SCH_PAGE')throw new Error('Candidate has wrong document identity');
if(!await eda.sys_FileManager.setDocumentSource(candidate))throw new Error('Source rejected; inspect before retry');
const actual=await eda.sys_FileManager.getDocumentSource();
const out=root+'/output/validation/native-adc10-labtool-page'+page+'-accepted-20261018.epru';
if(!await eda.sys_FileSystem.saveFileToFileSystem(out,new Blob([actual]),undefined,false))throw new Error('Accepted source not captured');
if(!await eda.sch_Document.save())throw new Error('Native schematic save failed; accepted source preserved');
return{page,uuid,candidateSha256:expectedHash,acceptedPath:out,saved:true,manufacturingReady:false};
